import sys, numpy as np, pandas as pd
from lmfit.models import LorentzianModel, PseudoVoigtModel, LinearModel, ConstantModel
from scipy.optimize import curve_fit

def lor(x, a, c, w, b0, b1):
    return a * (w/2)**2 / ((x-c)**2 + (w/2)**2) + b0 + b1*(x-500)

def fit_lor(x, y, lo, hi, p0, sigma=None):
    m = (x>=lo)&(x<=hi)
    popt, pcov = curve_fit(lor, x[m], y[m], p0=p0, sigma=sigma, absolute_sigma=False, maxfev=20000)
    return popt, np.sqrt(np.diag(pcov))

def fit_2lor(x, y, lo, hi, p0):
    def f(x, a1, c1, w1, a2, c2, w2, b0, b1):
        return (a1*(w1/2)**2/((x-c1)**2+(w1/2)**2) + a2*(w2/2)**2/((x-c2)**2+(w2/2)**2) + b0 + b1*(x-500))
    m=(x>=lo)&(x<=hi)
    popt, pcov = curve_fit(f, x[m], y[m], p0=p0, maxfev=40000)
    return popt, np.sqrt(np.diag(pcov))

for p in sys.argv[1:]:
    df = pd.read_csv(p); x = df.shift_cm1.values; y = df.intensity.values
    print("==", p.split('/')[-1])
    # Si: several windows
    for lo, hi in [(510,532),(505,537),(500,540)]:
        po, pe = fit_lor(x, y, lo, hi, [900*(3.5/2)**2/(1)*0+900, 520.5, 3.5, 350, 0])
        # rescale amplitude param meaningless, print center
        print(f"  Si window {lo}-{hi}: center {po[1]:.3f} +/- {pe[1]:.3f}, FWHM {po[2]:.3f}")
    # E2g/A1g two-Lorentzian joint fit, windows
    for lo, hi in [(372,420),(365,430),(370,415)]:
        po, pe = fit_2lor(x, y, lo, hi, [900,384,2.5, 300,406,6, 360,0])
        print(f"  MoS2 2-Lor window {lo}-{hi}: E2g c={po[1]:.3f}+/-{pe[1]:.3f} w={po[2]:.2f}; A1g c={po[4]:.3f}+/-{pe[4]:.3f} w={po[5]:.2f}; delta={po[4]-po[1]:.3f}; hA1g/hE2g={ (po[3]/(po[5]/2)**2 *0 + po[3]) / po[0]:.3f}  (amp ratio)")
    # Check weak features: LA(M) ~227 and 2LA(M) ~450, E1g ~286
    base = np.median(y[(x>560)&(x<640)])
    for lo, hi, name in [(215,240,"LA(M)~227"),(280,292,"E1g~286"),(440,470,"2LA(M)~450"), (150, 180, "low-shift")]:
        m=(x>=lo)&(x<=hi)
        print(f"  {name}: max-smoothed excess over background-level {y[m].max()-np.median(y[m]):.1f}, mean {y[m].mean():.1f}, median {np.median(y[m]):.1f}")
    # noise estimate from second difference
    d2 = np.diff(y, 2)
    print(f"  robust noise (MAD of 2nd diff /sqrt6): {1.4826*np.median(np.abs(d2-np.median(d2)))/np.sqrt(6):.1f} counts")
EOF
